import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
import {escape as e} from './store.js';
let users=[],total=0,offset=0,query='',error='',loading=false,mailHistory=[],mailError='',configured=false,sending=false,stop=false;
export function resetUsers(){users=[];total=0;offset=0;query='';error='';mailHistory=[];mailError='';configured=false;stop=true;}
async function load(ui){const owner=backend.user()?.id;loading=true;error='';ui.render();try{const result=await backend.adminUsers(offset,query);if(backend.user()?.id!==owner)return;users=result.users;total=result.total;}catch(err){error=err.message;}finally{loading=false;ui.render();}}
export function usersScreen(){return `<section class="card"><div class="card-head"><h2>${copyHTML("users.6d3f7c7e3040")}</h2><span class="pill">${total} ${copyHTML("users.bc62a3c14fec")}</span></div><form id="users-search-form" class="toolbar"><input name="query" aria-label="${copyHTML("users.6934afec07b1")}" maxlength="100" placeholder="${copyHTML("users.8ce630fb6443")}" value="${e(query)}"><button class="btn">${copyHTML("users.49c266baaaa7")}</button></form><p class="muted">${copyHTML("users.9b24c80dd32d")}</p>${error?`<p role="alert">${e(error)} ${copyHTML("users.acb83f60c74d")}</p>`:''}${loading?`<p role="status">${copyHTML("users.a53ec7ac2a7b")}</p>`:users.map(u=>`<article class="user-record"><div><strong>${e(u.full_name)}</strong><p>@${e(u.username)} · ${e(u.disabled?'Disabled':'Active')}${u.is_admin?' · Administrator':''}</p><p>${copyHTML("users.17507dcf8457")} ${e(u.email||'—')}<br>${copyHTML("users.3305eb58093d")} ${e(u.phone_number||'Not provided')}<br>${e(u.institution)} · ${e(u.level)}</p></div><div class="actions">${u.is_admin?'':`<button class="btn" data-user-action="${u.disabled?'enable':'disable'}" data-user-id="${e(u.user_id)}">${u.disabled?'Re-enable':'Disable'}</button><button class="btn danger" data-user-action="delete" data-user-id="${e(u.user_id)}">${copyHTML("users.e2d0a54968ea")}</button>`}</div></article>`).join('')||`<p class="muted">${copyHTML("users.277fdaebdd67")}</p>`}<div class="actions"><button class="btn" id="users-prev" ${offset===0||loading?'disabled':''}>${copyHTML("users.a57b08a480b8")}</button><span>${total?offset+1:0}–${Math.min(offset+50,total)} ${copyHTML("users.28391d3bc64e")} ${total}</span><button class="btn" id="users-next" ${offset+50>=total||loading?'disabled':''}>${copyHTML("users.1ff57a29d7c9")}</button><button class="btn" id="users-refresh">${copyHTML("users.7e079f1e0f5a")}</button></div></section>`;}
export function mailScreen(){return `<section class="card"><div class="card-head"><h2>${copyHTML("users.0006b899320c")}</h2><button class="btn" id="mail-refresh">${copyHTML("users.70f3d21749cc")}</button></div><p class="muted">${copyHTML("users.dad3181604d0")}</p>${mailError?`<p role="alert">${e(mailError)}</p>`:''}${configured?'':`<div class="notice">${copyHTML("users.1e173c16e0e7")}</div>`}<form id="mail-compose"><label for="mail-subject">${copyHTML("users.68971283841a")}</label><input id="mail-subject" name="subject" required maxlength="180"><label for="mail-message">${copyHTML("users.2f77668a9dfb")}</label><textarea id="mail-message" name="message" rows="10" required maxlength="8000" placeholder="${copyHTML("users.bc0d43b54208")}"></textarea><p id="mail-compose-status" role="status"></p><button class="btn primary" ${sending?'disabled':''}>${copyHTML("users.f1c2e80222b1")}</button></form></section><section class="card"><h2>${copyHTML("users.456e72814017")}</h2>${mailHistory.map(j=>`<div class="row"><div class="row-copy"><strong>${e(j.subject)}</strong><small>${e(new Date(j.created_at).toLocaleString())}</small></div><button class="btn" data-mail-open="${e(j.id)}" ${sending?'disabled':''}>${copyHTML("users.468d89b9dcec")}</button></div>`).join('')||`<p class="muted">${copyHTML("users.3a75c645a9fb")}</p>`}</section>`;}
async function history(ui){mailError='';try{const data=await backend.adminMail({action:'history'});if(!backend.adminReady())return;mailHistory=data.jobs;configured=data.configured;}catch(err){mailError=err.message;}ui.render();}
function review(data,ui){const {job,counts}=data;ui.modal(copyRaw("users.1e7c6db5d3b3"),`<p><strong>${e(job.subject)}</strong></p><p class="mail-preview">${e(job.message)}</p><p id="mail-progress" role="status">${summary(counts)}</p>${(data.errors||[]).map(x=>`<p>${e(x.email)}: ${e(x.error)}</p>`).join('')}<p class="muted">${copyHTML("users.8fcdc3df7a68")}</p><div class="actions"><button class="btn primary" id="mail-send" ${!counts.pending?'disabled':''}>${counts.sent?'Resume pending':'Send to '+counts.pending+' recipients'}</button><button class="btn" id="mail-close">${copyHTML("users.7d9eb7acb13e")}</button></div>`);
 document.querySelector('#dialog').addEventListener('close',()=>{stop=true;},{once:true});
 document.querySelector('#mail-close').onclick=()=>{stop=true;document.querySelector('#dialog').close();};
 document.querySelector('#mail-send').onclick=async ev=>{if(sending)return;sending=true;stop=false;ev.target.disabled=true;const status=document.querySelector('#mail-progress');try{let current=data;while(!stop&&current.counts.pending){status.textContent=summary(current.counts)+' · Sending…';current=await backend.adminMail({action:'send',job_id:job.id});status.textContent=summary(current.counts)+(current.paused?' · '+current.paused:'');if(current.paused)break;}if(!current.counts.pending)status.textContent=summary(current.counts)+' · Finished.';ev.target.disabled=!current.counts.pending;ev.target.textContent=copyRaw("users.5ba07461e8c3");}catch(err){status.textContent=err.message;ev.target.disabled=false;ev.target.textContent=copyRaw("users.5ba07461e8c3");}finally{sending=false;}};
}
function summary(c){return `${c.total} recipients · ${c.sent} accepted · ${c.pending} pending · ${c.failed} failed · ${c.skipped} skipped`;}
function accountAction(action,id,ui){const user=users.find(u=>u.user_id===id);if(!user)return;ui.modal(`${action==='delete'?'Delete permanently':action==='disable'?'Disable account':'Re-enable account'}?`,`<p>${e(user.full_name)} (@${e(user.username)})</p><p class="muted">${action==='delete'?'This permanently deletes the account and linked platform profile and quiz results. Downloads already saved on their device remain. Type the username to confirm.':action==='disable'?'This blocks account access to protected content. Existing downloaded files and previously signed audio links remain accessible until those links expire.':'This restores account access.'}</p><form id="account-action-form">${action==='delete'?`<label for="delete-username">${copyHTML("users.e3b89e9d33f8")}</label><input id="delete-username" name="confirm" autocomplete="off" required>`:''}<p id="account-action-status" role="status"></p><div class="actions"><button class="btn ${action==='delete'?'danger':'primary'}">${copyHTML("users.eebdd24a77d9")} ${e(action)}</button><button type="button" class="btn" id="account-cancel">${copyHTML("users.19766ed6ccb2")}</button></div></form>`);document.querySelector('#account-cancel').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#account-action-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{await backend.adminAccount(action,id,new FormData(ev.target).get('confirm')||'');document.querySelector('#dialog').close();await load(ui);ui.toast(copyRaw("users.72b78a48527e"));}catch(err){document.querySelector('#account-action-status').textContent=err.message;button.disabled=false;}};}
export function bindUsers(ui){const f=document.querySelector('#users-search-form');if(f)f.onsubmit=ev=>{ev.preventDefault();query=new FormData(ev.target).get('query').trim();offset=0;load(ui);};const compose=document.querySelector('#mail-compose');if(compose)compose.onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const values=Object.fromEntries(new FormData(ev.target));const data=await backend.adminMail({action:'prepare',job_id:crypto.randomUUID(),...values});review(data,ui);}catch(err){document.querySelector('#mail-compose-status').textContent=err.message;}finally{button.disabled=false;}};}
export async function usersClick(button,ui){if(button.dataset.userAction){accountAction(button.dataset.userAction,button.dataset.userId,ui);return true;}if(['users-prev','users-next','users-refresh'].includes(button.id)){offset=button.id==='users-prev'?Math.max(0,offset-50):button.id==='users-next'?offset+50:offset;await load(ui);return true;}if(button.id==='mail-refresh'){await history(ui);return true;}if(button.dataset.mailOpen){try{review(await backend.adminMail({action:'status',job_id:button.dataset.mailOpen}),ui);}catch(err){ui.toast(err.message);}return true;}return false;}
export async function loadUsersTab(tab,ui){if(tab==='users')await load(ui);if(tab==='mail')await history(ui);}
